import{z as E,x as c,o as l,c as d,q as t,j as r,D as e,d as i,s,S as o,b as n}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"节距漂移","description":"","frontmatter":{"title":"节距漂移","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/pitch-walking.md","filePath":"litho/pitch-walking.md","lastUpdated":1791063341000}'),A={name:"litho/pitch-walking.md"};function h(m,a,D,g,B,k){const p=c("Mermaid");return l(),d("div",null,[a[2]||(a[2]=t('<h1 id="节距漂移" tabindex="-1">节距漂移 <a class="header-anchor" href="#节距漂移" aria-label="Permalink to &quot;节距漂移&quot;">​</a></h1><div class="epigraph"><p>侧墙把节距劈成两套间隔：芯轴侧与间隙侧。两者一不等，奇数间距与偶数间距就裂开，电学上像周期被「走」了一步。</p><footer>—— 据 SADP 计量对 pitch walking / odd–even space 的通称，以及芯轴–侧墙几何的误差传递</footer></div><p><a href="/litho/mandrel-spacer">上一课</a>把 \\(W_m\\)、\\(P_m\\) 与侧墙厚度 \\(t\\) 写成理想几何，并区分 core 与 gap。缺口是上线后这两套 space 通常不相等：mandrel CD、薄膜、回刻脚型只要偏一项，奇数间隔与偶数间隔就分裂。这就是节距漂移（pitch walking）。奇偶分裂在电学与计量上怎么分桶记账，留给<a href="/litho/odd-even-pitch">下一课</a>；切断掩模是后面的<a href="/litho/cut-mask-dpt">切断掩模</a>一课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>理想设计可以把 core 与 gap 画成同一个目标 space。计量上 CD-SEM 沿栅扫描，会看到交替的两种间隔。差值达到电阻、击穿或鳍宽度预算，阵列就是坏的——即使「平均节距」仍是 \\(P_m/2\\)，线宽均值也合格。LELE 的 \\(\\delta\\) 造成的也是相邻 space 一宽一窄；SADP 的 walking 不来自第二次线层 overlay，而来自芯轴与薄膜。</p><p>缺口因此是奇数/偶数误差及其计量，而不是再画一遍侧墙环。没有这项，切线课会把切偏和 pitch walking 混成一个 CDU。</p><p><span class="marginnote">「walking」的字面就是走路：本该每步等距的节距，实际像人走路忽而步大忽而步小。奇数间隔与偶数间隔各是一组「左步」和「右步」——平均步长完全正常，左右却不相等，走久了就偏出跑道。</span></p><h3 id="平均节距合格不等于没有-walking" tabindex="-1">平均节距合格不等于没有 walking <a class="header-anchor" href="#平均节距合格不等于没有-walking" aria-label="Permalink to &quot;平均节距合格不等于没有 walking&quot;">​</a></h3><p>只报 mean CD 与 mean pitch，会把交替误差平均掉。SADP 计量必须分别报 core space、gap space，或显式报 pitch walking（两者之差或对目标的交替残差）。只对「每条线」做一次 CD 抽样，采样相位若总落在同一种 space 上，会系统盲。</p><p><span class="marginnote">口语里的 pitch walking 有时也包含 SAQP 多轮之后更复杂的多套 space。本课先钉双重：两套间隔。四重是同一思想的更多桶。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>控制旋钮：mandrel CD（光刻剂量、OPC、刻蚀偏置）主要推 core；沉积 \\(t\\) 与回刻推线宽并轻微耦合两种 space；相邻芯轴的节距均匀性推 gap。补偿策略是把 mandrel CD 故意偏一点，使 core 与 gap 在刻蚀后对齐——这是校准，不是「自对准失败」。过度补偿会把线宽带出窗。</p><p><span class="marginnote">数字实例：目标两套 space 各 20 nm。若 core 实测 18、gap 实测 22，平均节距仍是 40 nm 的完美值，但 walking = 4 nm——只看平均值的报表会给满分，阵列却可能在 18 nm 那一侧先击穿。</span></p><p>计量：CD-SEM 对交替 space 分桶；散射测量要有对奇偶敏感的模型，否则拟合出一个假的单一 pitch。场内、晶圆半径、开口密度都要抽样，因为薄膜加载随图形变。</p><h3 id="与-lele-套刻指纹拆开" tabindex="-1">与 LELE 套刻指纹拆开 <a class="header-anchor" href="#与-lele-套刻指纹拆开" aria-label="Permalink to &quot;与 LELE 套刻指纹拆开&quot;">​</a></h3><p>LELE 相邻 space 差随扫描机 overlay 场内指纹变。SADP walking 随 mandrel CDU 与薄膜径向变，通常对套刻标记不敏感。拆源：看误差是否跟着对齐修正量走。跟着走的是 overlay；不跟着走而跟着 mandrel 剂量走的是 walking。</p>',16)),(l(),r(o,null,{default:e(()=>[s(p,{id:"mermaid-46",class:"mermaid",graph:"flowchart%20TD%0A%20%20WM%5B%22Mandrel%20CD%20%E5%81%8F%22%5D%20--%3E%20CORE%5B%22core%20space%20%E5%8F%98%22%5D%0A%20%20T%5B%22%E8%96%84%E8%86%9C%20%2F%20%E5%9B%9E%E5%88%BB%E5%81%8F%22%5D%20--%3E%20CD%5B%22%E7%BA%BF%E5%AE%BD%E5%8F%98%22%5D%0A%20%20PM%5B%22%E8%8A%AF%E8%BD%B4%E8%8A%82%E8%B7%9D%E4%B8%8D%E5%9D%87%22%5D%20--%3E%20GAP%5B%22gap%20space%20%E5%8F%98%22%5D%0A%20%20CORE%20--%3E%20PW%5B%22%E5%A5%87%E5%81%B6%E9%97%B4%E8%B7%9D%E5%88%86%E8%A3%82%22%5D%0A%20%20GAP%20--%3E%20PW%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=n("h2",{id:"机制",tabindex:"-1"},[i("机制 "),n("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=n("p",null,"一阶：正 spacer 下去芯轴后，core 随 \\(W_m\\) 单调变，gap 随 \\(P_m-W_m\\) 变。\\(t\\) 增加则线变宽，两种 space 都变窄，但若脚型不对称，两边收窄量不同，仍引入 walking。SAQP 第二轮把上一轮的 walking 再当「芯轴」复制，误差结构更碎，设计上有时故意用后切或填补来藏，但计量桶数要加。",-1)),(l(),r(o,null,{default:e(()=>[s(p,{id:"mermaid-53",class:"mermaid",graph:"flowchart%20TD%0A%20%20W%5B%22Mandrel%20CD%20%E5%A2%9E%E5%A4%A7%22%5D%20--%3E%20CORE%5B%22core%20space%20%E5%8F%98%E7%AA%84%22%5D%0A%20%20W%20--%3E%20GAP%5B%22gap%20space%20%E5%8F%98%E5%AE%BD%22%5D%0A%20%20T%5B%22%E4%BE%A7%E5%A2%99%E5%8E%9A%E5%BA%A6%20t%20%E5%A2%9E%E5%A4%A7%22%5D%20--%3E%20BOTH%5B%22%E7%BA%BF%E5%8F%98%E5%AE%BD%20%E4%B8%A4%E5%A5%97%20space%20%E5%90%8C%E5%8F%98%E7%AA%84%22%5D%0A%20%20T%20--%3E%20ASYM%5B%22%E8%84%9A%E5%9E%8B%E4%B8%8D%E5%AF%B9%E7%A7%B0%E5%88%99%E6%94%B6%E7%AA%84%E4%B8%8D%E5%90%8C%22%5D%0A%20%20ASYM%20--%3E%20PW%5B%22%E6%AE%8B%E4%BD%99%20pitch%20walking%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[i(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=t('<p><span class="marginnote">初学者容易以为 mandrel CD 偏了就是光刻失败。实际上工程师会故意把芯轴印偏一点，让刻蚀后的 core 与 gap 对齐——这是补偿，不是失误。判断标准是刻蚀后的分桶结果，不是光刻后单张 SEM 好不好看。</span></p><p>电性：一种 space 偏窄先击穿或先变成鳍桥；另一种偏宽先掉电流。所以 walking 是可靠性与失配问题，不只是「平均 CD 还在规格里」。</p><p>上一课允许把 core 与 gap 设计成相等。量产校准是用 mandrel 剂量和刻蚀偏置把两者拉齐，而不是假设 ALD 厚度均匀就自动对齐。阵列边缘微负载会留下一圈走步，计量 ROI 要声明是否含边缘。</p><p><span class="marginnote">不要用单次曝光 \\(k_1\\) 去解释 walking。光学只约束芯轴能不能印；奇偶差在薄膜与芯轴 CD 上，瑞利公式里没有这一项。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把切线套刻写成 pitch walking：切偏的是线端位置，周期沿栅仍可以奇偶合格。把线切短是后面切断课的事。也不编 7 nm 鳍的 walking 纳米规格。公开讨论停在：SADP 必须分桶计量奇偶 space。</p><p>二维局部、线端附近的 spacer 环会让「奇偶」定义模糊，计量 ROI 要避开切区与阵列边缘，否则把几何过渡区当成 walking。</p><p><span class="marginnote">校正环若只用平均 CD 做 APC，会把 walking 锁死在一个不等于零的值。剂量拧到均值合格，奇偶差依旧。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Pitch walking 是 SADP 的 core / gap 不相等，表现为奇偶间距分裂。</li><li>旋钮主要是 mandrel CD 与薄膜；不是第二次线层 overlay。</li><li>计量必须分桶，平均节距会掩盖问题。</li><li>与 LELE 的 \\(\\delta\\) 指纹要拆源。</li><li>奇偶节距的桶数下一课；切断掩模随后。</li><li>出处：SADP 计量对 pitch walking 的通称；上一课芯轴–侧墙几何。</li></ul>',10))])}const w=E(A,[["render",h]]);export{_ as __pageData,w as default};
